module traffic_light(
    input rst_n, input clk, input pass_request,
    output [7:0] clock, output red, yellow, green
);
// Design Track
// First always block for state transition logic
reg [1:0] state, next_state;
reg [7:0] cnt, next_cnt;
reg p_red, p_yellow, p_green;
localparam idle = 2'b00, s1_red = 2'b01, s2_yellow = 2'b10, s3_green = 2'b11;
always @(*) begin
    case(state)
        idle: next_state = s1_red;
        s1_red: begin
            if(cnt == 3) next_state = s3_green;
            else next_state = s1_red;
        end
        s2_yellow: begin
            if(cnt == 3) next_state = s1_red;
            else next_state = s2_yellow;
        end
        s3_green: begin
            if(cnt == 3) next_state = s2_yellow;
            else next_state = s3_green;
        end
        default: next_state = idle;
    endcase
end
// Second always block for counting logic
always @(*) begin
    if(!rst_n) next_cnt = 8'd10;
    else if(pass_request && green && (cnt > 10)) next_cnt = 8'd10;
    else if(!green && p_green) next_cnt = 8'd60;
    else if(!yellow && p_yellow) next_cnt = 8'd5;
    else if(!red && p_red) next_cnt = 8'd10;
    else next_cnt = cnt - 1;
end
// Third always block for output assignment
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        state <= idle;
        cnt <= 8'd10;
        {p_red, p_yellow, p_green} <= 3'b000;
    end else begin
        state <= next_state;
        cnt <= next_cnt;
        {p_red, p_yellow, p_green} <= {red, yellow, green};
    end
end
assign red = (state == s1_red || state == s3_green) ? 1'b1 : 1'b0;
assign yellow = (state == s2_yellow) ? 1'b1 : 1'b0;
assign green = (state == s3_green) ? 1'b1 : 1'b0;
assign clock = cnt;
endmodule
